-- #49: additive response metadata. Apply only after existing dictionary migrations through 20261021.
-- Generated by Supabase CLI; historical 8-digit file dates are not a complete remote ledger.
-- Preserve all search predicates, publication filtering, signatures and ACLs. No data/schema deletion.
begin;
do $$ begin
 if to_regprocedure('public.search_dictionary_with_inflections(text,text,integer)') is null
 or to_regprocedure('public.publish_dictionary_entry(uuid,boolean)') is null then
  raise exception 'Apply dictionary migrations through 20261021 before pagination totals';
 end if;
end $$;

create or replace function public.search_published_dictionary(category text default 'word', query_text text default '', page_number integer default 0)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if category is null or category not in ('all','word','prefix','root') then raise exception 'Invalid category'; end if;
  if page_number is null or page_number<0 or page_number>100000 then raise exception 'Invalid page'; end if;
  if query_text is null or length(query_text)>120 then raise exception 'Invalid query'; end if;
  with matches as (
    select id,kind,headword from public.dictionary_entries
    where status='published' and (category='all' or kind=category)
      and strpos(lower(headword),lower(btrim(query_text)))>0
  ), page_rows as (select * from matches order by headword,id limit 21 offset page_number*20), shown as (select * from page_rows order by headword,id limit 20)
  select jsonb_build_object('items',coalesce((select jsonb_agg(s order by headword,id) from shown s),'[]'::jsonb),
    'has_more',(select count(*)>20 from page_rows),'page',page_number,'total',(select count(*) from matches)) into result;
  return result;
end $$;

create or replace function public.search_prefix_dictionary(query_text text default '',page_number integer default 0,primary_category_filter text default '__ungrouped__')
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if page_number is null or page_number<0 or page_number>100000 then raise exception 'Invalid page'; end if;
  if query_text is null or length(query_text)>120 then raise exception 'Invalid query'; end if;
  if primary_category_filter is null or primary_category_filter not in ('__ungrouped__','性質、評價與否定','位置、方向與關係','數值、量與程度','作用與變化') then raise exception 'Invalid prefix group'; end if;
  with matches as (
    select e.id,e.kind,e.headword,s.id as sense_id,s.gloss_zh_tw,g.primary_category
    from public.dictionary_entries e join public.dictionary_senses s on s.entry_id=e.id
    left join public.dictionary_sense_groups g on g.sense_id=s.id
    where e.kind='prefix' and e.status='published' and strpos(lower(e.headword),lower(btrim(query_text)))>0
      and (case when primary_category_filter='__ungrouped__' then g.primary_category is null else g.primary_category=primary_category_filter end)
  ), page_rows as (select * from matches order by headword,id,sense_id limit 21 offset page_number*20), shown as (select * from page_rows order by headword,id,sense_id limit 20)
  select jsonb_build_object('items',coalesce((select jsonb_agg(s order by headword,id,sense_id) from shown s),'[]'::jsonb),
    'has_more',(select count(*)>20 from page_rows),'page',page_number,'total',(select count(*) from matches)) into result;
  return result;
end $$;

create or replace function public.search_grouped_dictionary(category text,query_text text default '',page_number integer default 0,primary_category_filter text default '__ungrouped__')
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
  if category='prefix' then return public.search_prefix_dictionary(query_text,page_number,primary_category_filter); end if;
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if category is null or category not in ('prefix','root') then raise exception 'Invalid category'; end if;
  if page_number is null or page_number<0 or page_number>100000 then raise exception 'Invalid page'; end if;
  if query_text is null or length(query_text)>120 then raise exception 'Invalid query'; end if;
  if primary_category_filter is null or primary_category_filter not in ('__ungrouped__','空間、位置與環境','動作、接觸與物理作用','移動、轉變與方向','物質、自然與元素','生命、身體與感官','情感、心理與意志','心智、溝通與學習','社會、法律與制度','時間、狀態、數量與邏輯') then raise exception 'Invalid group'; end if;
  with matches as (
    select e.id,e.kind,e.headword,g.primary_category,g.tags,g.variant_group
    from public.dictionary_entries e left join public.dictionary_entry_groups g on g.id=e.id
    where e.status='published' and e.kind=category and strpos(lower(e.headword),lower(btrim(query_text)))>0
      and (case when primary_category_filter='__ungrouped__' then g.primary_category is null else g.primary_category=primary_category_filter end)
  ), page_rows as (select * from matches order by headword,id limit 21 offset page_number*20), shown as (select * from page_rows order by headword,id limit 20)
  select jsonb_build_object('items',coalesce((select jsonb_agg(s order by headword,id) from shown s),'[]'::jsonb),'has_more',(select count(*)>20 from page_rows),'page',page_number,'total',(select count(*) from matches)) into result;
  return result;
end $$;

create or replace function public.search_dictionary_relation_targets(query_text text default '',page_number integer default 0) returns jsonb language sql stable security definer set search_path='' as $$
 with all_matches as (
  select e.id,e.headword,e.kind,coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'gloss_zh_tw',s.gloss_zh_tw,'part_of_speech',s.part_of_speech) order by s.id) from public.dictionary_senses s where s.entry_id=e.id),'[]') senses
  from public.dictionary_entries e where public.is_dictionary_admin() and e.status='published'
   and (strpos(lower(e.headword),lower(btrim(query_text)))>0 or exists(select 1 from public.dictionary_senses s where s.entry_id=e.id and strpos(lower(s.gloss_zh_tw),lower(btrim(query_text)))>0))
 ), matches as (select * from all_matches order by headword,id limit 21 offset greatest(page_number,0)*20) select jsonb_build_object('items',coalesce((select jsonb_agg(x order by x.headword,x.id) from (select * from matches limit 20) x),'[]'),'total',(select count(*) from all_matches),'has_more',(select count(*)>20 from matches),'page',greatest(page_number,0));
$$;

create or replace function public.search_dictionary_with_inflections(category text default 'all',query_text text default '',page_number integer default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if category is null or category not in ('all','word','prefix','root') or query_text is null or length(query_text)>120 or page_number is null or page_number<0 then raise exception 'Invalid dictionary search';end if;
 return (with all_matches as (
  select e.id,e.kind,e.headword,coalesce((select jsonb_agg(jsonb_build_object('form',i.form,'form_kind',i.form_kind,'sense_id',i.sense_id) order by i.sort_order,i.id) from public.dictionary_inflections i where i.entry_id=e.id and lower(btrim(i.form))=lower(btrim(query_text))),'[]') inflection_matches
  from public.dictionary_entries e where auth.uid() is not null and e.status='published' and (category='all' or e.kind=category)
   and (strpos(lower(e.headword),lower(btrim(query_text)))>0 or exists(select 1 from public.dictionary_senses s where s.entry_id=e.id and strpos(lower(s.gloss_zh_tw),lower(btrim(query_text)))>0) or exists(select 1 from public.dictionary_inflections i where i.entry_id=e.id and lower(btrim(i.form))=lower(btrim(query_text))))
 ), matches as (select * from all_matches order by headword,id limit 21 offset greatest(page_number,0)*20) select jsonb_build_object('items',coalesce((select jsonb_agg(x order by x.headword,x.id) from (select * from matches limit 20) x),'[]'),'total',(select count(*) from all_matches),'has_more',(select count(*)>20 from matches),'page',greatest(page_number,0)));
end $$;

notify pgrst,'reload schema';
commit;
